    ctx.fillStyle = g; ctx.beginPath(); ctx.moveTo(X - 3, Y - hgt); ctx.lineTo(X + 3, Y - hgt); ctx.lineTo(X + wid, Y); ctx.lineTo(X - wid, Y); ctx.fill();
    const r = ctx.createRadialGradient(X, Y, 1, X, Y, wid); r.addColorStop(0, 'rgba(255,240,170,' + (a * 1.6) + ')'); r.addColorStop(1, 'rgba(255,240,170,0)');
